bin/git.text:
#!/bin/sh
d=$(dirname "$0")
echo "$*" >> "$d/git.log"
case "$*" in
  *'rev-parse --verify -q refs/remotes/origin/main^{commit}') exit 0;;
  *'cat-file -e refs/remotes/origin/main:.claude/ah-conventions.json') exit 128;;
  *) exit 1;;
esac

